"""Science, Year 8 (KS3).

KS3 science is one programme of study for Years 7 to 9. The split agreed for this app puts these in
Year 8:

* Biology: nutrition and digestion (healthy diet, energy requirements, imbalances and deficiency
  diseases, the digestive system and enzymes, gut bacteria, plant nutrition through leaves and roots);
  gas exchange systems (structure of the human gas exchange system, breathing and the pressure model,
  lung volume, exercise, asthma and smoking, stomata in plants); respiration (aerobic and anaerobic,
  fermentation, word summaries, differences); photosynthesis (word summary, dependence of life on
  photosynthesis, leaf adaptations).
* Chemistry: atoms, elements and compounds (Dalton's model, symbols and formulae, conservation of mass,
  changes of state); the periodic table (Mendeleev, periods and groups, metals and non-metals and their
  properties, acidity of oxides, groups 1, 7 and 0, predicting patterns); chemical reactions
  (rearrangement of atoms, word and simple symbol equations read not written, physical and chemical
  changes, combustion, oxidation, thermal decomposition, displacement, catalysts).
* Physics: light (light waves and waves in matter, vacuum, speed of light, absorption, diffuse
  scattering and specular reflection, the law of reflection and plane mirrors, refraction and convex
  lenses, the pinhole camera, the eye, photo-sensitive materials and the chemical and electrical effects
  of light, colour and frequency, prisms, coloured objects and filters); electricity (current in series
  and parallel circuits, potential difference and ratings, resistance R = V / I, conductors and
  insulators, static electricity, electric fields); magnetism (poles, fields and field lines, Earth's
  magnetism and compasses, electromagnets and how to make them stronger, D.C. motors in principle);
  energy (work done = force x distance, simple machines, temperature difference and thermal equilibrium,
  conduction, convection, radiation, insulators, energy stores and transfers, conservation and
  dissipation, fuels and energy resources).

Each statutory statement has its own skill; broad statements are split into separate lessons. All
other KS3 statements belong to Years 7 and 9.
"""

